    n = len(grid)
    # Flip over the main diagonal: swap each cell above it with its mirror.
    for r in range(n):
        for c in range(r + 1, n):
            grid[r][c], grid[c][r] = grid[c][r], grid[r][c]
    # Then reverse each row.
    for row in grid:
        row.reverse()


