import java.util.Scanner;

public class Main {
    static void rotateMatrix(int[][] grid) {
        int n = grid.length;
        // Flip over the main diagonal: swap each cell above it with its mirror.
        for (int r = 0; r < n; r++) {
            for (int c = r + 1; c < n; c++) {
                int temp = grid[r][c];
                grid[r][c] = grid[c][r];
                grid[c][r] = temp;
            }
        }
        // Then reverse each row.
        for (int[] row : grid) {
            for (int left = 0, right = n - 1; left < right; left++, right--) {
                int temp = row[left];
                row[left] = row[right];
                row[right] = temp;
            }
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int rows = in.nextInt();
        int cols = in.nextInt();
        int[][] grid = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = in.nextInt();
            }
        }
        rotateMatrix(grid);
        for (int[] row : grid) {
            StringBuilder line = new StringBuilder();
            for (int c = 0; c < row.length; c++) {
                if (c > 0) {
                    line.append(" ");
                }
                line.append(row[c]);
            }
            System.out.println(line);
        }
    }
}

