import "fmt"

func rotateMatrix(grid [][]int) {
	n := len(grid)
	// Flip over the main diagonal: swap each cell above it with its mirror.
	for r := 0; r < n; r++ {
		for c := r + 1; c < n; c++ {
			grid[r][c], grid[c][r] = grid[c][r], grid[r][c]
		}
	}
	// Then reverse each row.
	for _, row := range grid {
		for left, right := 0, n-1; left < right; left, right = left+1, right-1 {
			row[left], row[right] = row[right], row[left]
		}
	}
}

