import { readFileSync } from "node:fs";

const tokens = readFileSync(0, "utf8").trim().split(/\s+/).map(Number);

function rotateMatrix(grid: number[][]): void {
  // Flip over the main diagonal: swap each cell above it with its mirror.
  for (const [r, row] of grid.entries()) {
    for (let c = r + 1; c < grid.length; c++) {
      const other = grid[c];
      if (other !== undefined) {
        [row[c], other[r]] = [other[r] ?? 0, row[c] ?? 0];
      }
    }
  }
  // Then reverse each row.
  for (const row of grid) {
    row.reverse();
  }
}

